566:{
567:    sc_context_t *ctx = *state;
568:    struct sc_asn1_entry asn1[] = {
569:            { "OctetString", SC_ASN1_OCTET_STRING, 0x05, SC_ASN1_PRESENT, NULL, NULL },
570:            { NULL , 0 , 0 , 0 , NULL , NULL }
571:    };
572:    u8 expected[] = {0x05, 0x09, 't', 'e', 's', 't', ' ', 'd', 'a', 't', 'a'};
573:    char *data = "test data";
574:    size_t datalen = strlen(data);
575:    u8 *outptr = NULL;
576:    size_t outlen = 0;
577:    int rv;
578:
579:    /* NULL arguments should not crash */
580:    rv = sc_asn1_encode(NULL, NULL, NULL, NULL);
581:    assert_int_equal(rv, SC_ERROR_INVALID_ARGUMENTS);
582:
583:    /* NULL asn1 entry should not crash */
584:    rv = sc_asn1_encode(ctx, NULL, NULL, NULL);
585:    assert_int_equal(rv, SC_ERROR_INVALID_ARGUMENTS);
586:
587:    /* Real example of encoding an octet string */
588:    asn1[0].parm = data;
589:    asn1[0].arg = &datalen;
590:    rv = sc_asn1_encode(ctx, asn1, &outptr, &outlen);
591:    assert_int_equal(rv, SC_SUCCESS);
592:    assert_int_equal(outlen, sizeof(expected));
593:    assert_memory_equal(expected, outptr, sizeof(expected));
594:    free(outptr);
595:
596:    /* Context is not needed */
597:    rv = sc_asn1_encode(NULL, asn1, &outptr, &outlen);
598:    assert_int_equal(rv, SC_SUCCESS);
599:    free(outptr);
600:}
